extends "res://htd/htd_test.gd"


func _run_tests() -> void:
	var main := await instantiate_main_scene()
	if not check("main", main != null, "La scena principale deve avviarsi senza errori"):
		return
	var btn := find_by_name(main, "PlayButton") as Button
	var title := find_by_name(main, "TitleLabel") as Label
	if not check("elements", btn != null and title != null, "La scena principale deve contenere PlayButton e TitleLabel"):
		return
	await click_button(btn)
	check("click", title.text == "Partita Avviata", "Premendo Gioca il titolo deve diventare 'Partita Avviata'")

